	slotAddr = m.LvIdTab + id<<2
	node = rt.Ld32(m.Mem, int(slotAddr))
	rt.St32(m.Mem, int(node)+4, rt.Ld32(m.Mem, int(node)+4)-1)
	if rt.Ld32(m.Mem, int(node)+4) != 0 {
		return
	}
	prev = m.LvBuckets + (rt.Ld32(m.Mem, int(node)+12)&m.LvBucketMask)<<2
