// LiveStats is (export "liveStats").
func (m *Machine) LiveStats(k uint32) uint32 {
	if k == 0 {
		return m.LvRetok
	}
	if k == 1 {
		return m.LvStateCount
	}
	if k == 2 {
		return m.LvStateBytes
	}
	if k == 3 {
		return m.LvHeapLive
	}
	if k == 4 {
		return m.LvHeapFreed
	}
	if k == 5 {
		return m.LvInitialDead
	}
	if k == 6 {
		return 2288
	}
	if k == 7 {
		return m.LvHeapEnd
	}
	if k == 8 {
		return m.LvHeapCeil
	}
	if k == 9 {
		return m.LvPhase
	}
	if k == 10 {
		return m.LvCursor
	}
	if k == 11 {
		return m.LvChangeIdx
	}
	return 0
}

// Highlight is (export "highlight").
func (m *Machine) Highlight() {
	m.SrcBase = 0x14000
	m.DocStart = 0x14000
	m.Streaming = 0
	m.StreamDepth = 0
	m.SigReset()
	m.HlBegin()
	m.HighlightLang(rt.Ld8(m.Mem, 0))
	m.HlEnd()
}

// StreamResetGlobals is $streamResetGlobals.
func (m *Machine) StreamResetGlobals() {
	m.EcmaImport = 0
	rt.Fill(m.Mem, 13952, 0, 32)
	m.StreamClearCheckpoints()
	m.StreamMode = 0
	m.StreamA = 0
	m.StreamB = 0
	m.StreamC = 0
	m.StreamHl = 0
	m.StreamRegionKind = 0
	m.StreamRegionStarted = 0
	m.MarkdownStreamFence = 0
	m.MarkdownStreamFenceLen = 0
	m.MarkdownStreamLang = 0
	rt.Fill(m.Mem, 45104, 0, 96)
	m.PhpStreamingCode = 0
	m.PhpStreamDecl = 0
	m.PhpStreamMember = 0
}

// StreamChunk is $streamChunk.
func (m *Machine) StreamChunk(lang uint32, reset uint32) {
	var t1 bool
	var t2 uint32
	m.LiveEntering = 1
	if m.EcmaStreamLang(lang, reset) != 0 {
		return
	}
	if m.LiveSuspended != 0 {
		m.HighlightLang(lang)
		return
	}
	m.LiveEntering = 0
	if reset != 0 {
		m.SigReset()
	}
	t1 = lang == 87 || lang == 89
	t2 = m.MarkdownFenceReg()
	if t1 && t2 != 0 {
		if m.MarkdownStreamResume() != 0 {
			return
		}
		m.HighlightLang(lang)
		return
	}
	if m.StreamRegionKind != 0 {
		if m.StreamResumeLang(lang) != 0 {
			return
		}
	}
	if m.StreamResumeCommon() != 0 {
		return
	}
	if m.StreamResumeLang(lang) != 0 {
		return
	}
	m.LiveEntering = 1
	m.HighlightLang(lang)
}

// HighlightStream is (export "highlightStream").
func (m *Machine) HighlightStream(reset uint32) {
	m.SrcBase = 0x14000
	m.Streaming = 1
	m.StreamReset = reset
	m.DocStart = rt.Sel32(reset != 0, 0x14000, 0)
	m.StreamDepth = 0
	if reset != 0 {
		m.StreamResetGlobals()
	}
	m.HlBegin()
	m.RecStreamBegin(reset)
	m.StreamChunk(rt.Ld8(m.Mem, 0), reset)
	m.RecStreamEnd()
	m.HlEnd()
	m.Streaming = 0
	m.StreamDepth = 0
}
